function validate([text, w, h, fonts]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 50000) return 'text has 1 to 50000 characters.';
  if (!/^[a-z]+$/.test(text)) return 'text uses only lowercase English letters.';
  if (!Number.isInteger(w) || w < 1 || w > 1e7) return 'w is a whole number from 1 to 10^7.';
  if (!Number.isInteger(h) || h < 1 || h > 1e4) return 'h is a whole number from 1 to 10^4.';
  if (!Array.isArray(fonts) || fonts.length < 1 || fonts.length > 1e5) return 'fonts has 1 to 10^5 sizes.';
  for (let i = 0; i < fonts.length; i++) {
    if (!Number.isInteger(fonts[i]) || fonts[i] < 1 || fonts[i] > 1e5) return 'Each font size is a whole number from 1 to 10^5.';
    if (i > 0 && fonts[i] <= fonts[i - 1]) return 'fonts must be strictly increasing, with no duplicates.';
  }
  return null;
}

