function adapt(input, solve, kit) {
  const [text, w, h, fonts] = input;
  const checkSize = (fontSize, method) => {
    if (!Number.isInteger(fontSize) || fontSize < 1) throw new Error(`fontInfo.${method} needs a positive whole-number font size, not ${fontSize}.`);
  };
  // The judge's font: every letter is fontSize tall and fontSize + (alphabet position % 3) wide.
  const fontInfo = Object.freeze({
    getWidth(fontSize, ch) {
      checkSize(fontSize, 'getWidth');
      if (typeof ch !== 'string' || !/^[a-z]$/.test(ch)) throw new Error(`fontInfo.getWidth needs one lowercase letter, not ${JSON.stringify(ch)}.`);
      return fontSize + (ch.charCodeAt(0) - 96) % 3;
    },
    getHeight(fontSize) {
      checkSize(fontSize, 'getHeight');
      return fontSize;
    },
  });
  const result = solve(text, w, h, fonts.slice(), fontInfo);
  if (!Number.isInteger(result)) throw new Error('Return a font size from fonts, or -1.');
  return result;
}

