function maxFont(text, w, h, fonts, fontInfo) {
  function fits(fontSize) {
    if (fontInfo.getHeight(fontSize) > h) {
      return false;
    }
    let width = 0;
    for (const ch of text) {
      width += fontInfo.getWidth(fontSize, ch);
      if (width > w) {
        return false;
      }
    }
    return true;
  }

  let left = 0;
  let right = fonts.length - 1;
  let answer = -1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (fits(fonts[mid])) {
      answer = fonts[mid];
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return answer;
}

