function maxFont(text, w, h, fonts, fontInfo) {
  // Count each letter once, then try every size without relying on monotonicity.
  const counts = new Map();
  for (const ch of text) counts.set(ch, (counts.get(ch) || 0) + 1);
  let best = -1;
  for (const size of fonts) {
    let total = 0;
    for (const [ch, count] of counts) total += count * fontInfo.getWidth(size, ch);
    if (total <= w && fontInfo.getHeight(size) <= h && size > best) best = size;
  }
  return best;
}

