function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const widthAt = (text, fontSize) => {
    let total = 0;
    for (const ch of text) total += fontSize + (ch.charCodeAt(0) - 96) % 3;
    return total;
  };
  const large = size === 'large';
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const letters = large ? 26 : int(1, 26);
  const length = large ? int(1000, 8000) : int(1, 8);
  let text = '';
  for (let i = 0; i < length; i++) text += alphabet[int(0, letters - 1)];
  // Sizes up to cap keep the width, plus slack, within w's limit of 10^7.
  const cap = large ? Math.floor(1e7 / length) - 3 : 30;
  const top = large ? Math.min(1e5, 2 * cap) : 30;
  const count = large ? 2000 : int(1, 8);
  const chosen = new Set();
  while (chosen.size < count) chosen.add(int(1, top));
  const fonts = [...chosen].sort((a, b) => a - b);
  const usable = fonts.filter(f => f <= cap).length;
  const target = int(0, Math.max(0, usable - 1));
  const roll = rand();
  // Usually the width decides the answer at fonts[target]; sometimes the text never fits or the height decides.
  let w = Math.min(1e7, widthAt(text, fonts[target]) + int(0, length - 1));
  if (!large && roll < 0.2) w = int(1, widthAt(text, fonts[0]));
  let h = large ? 1e4 : int(fonts[target], 40);
  if (rand() < 0.3) h = int(1, Math.min(1e4, fonts[target]));
  return [text, w, h, fonts];
}
